首先，我将创建项目目录和必要的初始化文件。

```json
{
  "action": "create_directory",
  "args": {
    "path": "my-portfolio"
  }
}
```

```json
{
  "action": "create_directory",
  "args": {
    "path": "my-portfolio"
  }
}
```

```json
{
  "action": "list_files",
  "args": {
    "path": "my-portfolio"
  },
  "rationale": "为了了解当前目录下的文件结构，以便后续的开发任务。"
}
```

```json
{
  "action": "create_directory",
  "args": {
    "path": "my-portfolio/src"
  },
  "rationale": "根据用户需求，需要一个 src 目录来存放 React 组件。"
}
```

```json
{
  "action": "list_files",
  "args": {
    "path": "my-portfolio/src"
  },
  "rationale": "查看 src 目录下是否存在文件，以便确定下一步创建哪些文件。"
}
```

```json
{
  "action": "create_directory",
  "args": {
    "path": "my-portfolio/src/components"
  },
  "rationale": "根据项目目标和用户需求，创建组件目录，方便后续组织组件代码。"
}
```

```json
{
  "action": "run_command",
  "args": {
    "command": "npm install react vite @vitejs/plugin-react"
  },
  "rationale": "根据用户要求，使用 React 和 Vite 构建网站，需要安装相应的依赖包。"
}
```
